import * as THREE from 'three';
import { archivePointPosition, nearbyArchivePoints } from './museumArchive.js';

export const ARCHIVE_CENTRE = [16.7, 0, 3.4];
export const archiveZoom = value => THREE.MathUtils.clamp(value, 1, 1.75);
const MAX_PITCH = .35;

// Approach the installation along the floor. Its physical volume never grows.
export function archiveDollyPosition(position, previousZoom, nextZoom) {
  const dx=position.x-ARCHIVE_CENTRE[0], dz=position.z-ARCHIVE_CENTRE[2];
  const distance=Math.hypot(dx,dz);
  if(!distance)return position.clone();
  const next=THREE.MathUtils.clamp(distance*previousZoom/nextZoom,3.5,10);
  return new THREE.Vector3(ARCHIVE_CENTRE[0]+dx*next/distance,position.y,ARCHIVE_CENTRE[2]+dz*next/distance);
}

export function createMuseumArchiveObject({ scene, stone, edge, paper, metal, box, lettering, targets, invalidate }) {
  const group = new THREE.Group();group.position.fromArray(ARCHIVE_CENTRE);scene.add(group);
  const cylinder = (radius, height, material, y) => {
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, height, 64), material);
    mesh.position.y = y;mesh.castShadow = true;mesh.receiveShadow = true;group.add(mesh);return mesh;
  };
  cylinder(2.45, .12, edge, .06);
  cylinder(1.92, .73, stone, .47);
  cylinder(2.18, .045, metal, .85);
  cylinder(2.2, .09, paper, .935);
  cylinder(1.76, .012, edge, .987);
  cylinder(1.73, .014, paper, .997);
  const miniature = group.clone(true);
  const volume = new THREE.Group();volume.position.y = 2.42;volume.rotation.y = -.38;group.add(volume);
  const content = new THREE.Group();volume.add(content);
  const nodesMaterial = new THREE.MeshBasicMaterial({ color:'#ffffff', toneMapped:false });
  const linesMaterial = new THREE.LineBasicMaterial({ transparent:true, opacity:0, depthWrite:false, toneMapped:false });
  const lines = new THREE.LineSegments(new THREE.BufferGeometry(), linesMaterial);content.add(lines);
  const neighbourhoodMaterial = new THREE.LineBasicMaterial({ transparent:true, opacity:.32, depthWrite:false, toneMapped:false });
  const neighbourhood = new THREE.LineSegments(new THREE.BufferGeometry(), neighbourhoodMaterial);content.add(neighbourhood);
  const ring = new THREE.Mesh(new THREE.TorusGeometry(.105,.007,6,40), new THREE.MeshBasicMaterial({ transparent:true, opacity:0, toneMapped:false }));
  ring.visible = false;content.add(ring);
  const title = lettering('Henry’s archive',3.2,.4,16.7,.6,5.365,92);title.rotation.x=-.1;
  targets.push({ area:'archive', mesh:box(5.2,4.4,5.2,new THREE.MeshBasicMaterial({visible:false}),16.7,2.2,3.4) });
  // Only the space above the tabletop accepts direct manipulation.
  const controlVolume = new THREE.Mesh(new THREE.CylinderGeometry(2.12,2.12,2.8,32),new THREE.MeshBasicMaterial({visible:false,side:THREE.DoubleSide}));
  controlVolume.position.y=2.44;group.add(controlVolume);
  const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();
  const light = new THREE.PointLight('#eed8b1',3,6,2);light.position.set(0,1.1,0);group.add(light);
  const pixels=new Uint8Array(32*32*4);
  for(let y=0;y<32;y++)for(let x=0;x<32;x++){
    const i=(y*32+x)*4,d=Math.hypot(x-15.5,y-15.5)/15.5;
    pixels[i]=pixels[i+1]=pixels[i+2]=255;pixels[i+3]=Math.round(Math.max(0,1-d)**3*255);
  }
  const haloTexture=new THREE.DataTexture(pixels,32,32);haloTexture.needsUpdate=true;
  const haloMaterial=new THREE.PointsMaterial({size:.15,map:haloTexture,transparent:true,opacity:.12,depthWrite:false,toneMapped:false});
  const halos=new THREE.Points(new THREE.BufferGeometry(),haloMaterial);content.add(halos);
  let points=[],positions=new Map(),nodes=null,selectedId=null,selected=null,highlights=new Set(),related=new Set();
  let rotation=-.38,pitch=0,zoom=1,currentRotation=rotation,currentPitch=0,currentZoom=1,currentHoverScale=1;
  let lineEnds=[],emphasis=1,theme=0,themeFrom=0,themeTo=0;
  let weights=[];const hoverSources=new Set();
  const dummy=new THREE.Object3D(),baseColor=new THREE.Color(),selectedColor=new THREE.Color(),color=new THREE.Color();
  const day={base:new THREE.Color('#4d585b'),accent:new THREE.Color('#91632b')};
  const night={base:new THREE.Color('#b8c7cb'),accent:new THREE.Color('#f5d8a5')};
  const tones=[
    [new THREE.Color('#4d626d'),new THREE.Color('#b2cbd6')],
    [new THREE.Color('#63705b'),new THREE.Color('#c1ceb0')],
    [new THREE.Color('#7c655c'),new THREE.Color('#d8bfb0')],
  ];
  const toneFor=point=>/^\/(about|travels|education|home|cv)(?:\/|$)/.test(point.route||'')?1:/^\/(fragments|early|views)(?:\/|$)/.test(point.route||'')?2:0;
  const pointPosition=point=>positions.get(point.id);
  function rebuildSelection(){
    selected=points.find(point=>point.id===selectedId);
    const vertices=[],neighbours=selected?nearbyArchivePoints(points,selectedId,5):[];related=new Set(neighbours.map(point=>point.id));
    if(selected)for(const point of neighbours)vertices.push(...pointPosition(selected),...pointPosition(point));lineEnds=vertices;
    lines.geometry.dispose();lines.geometry=new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));
    ring.visible=Boolean(selected);if(selected)ring.position.fromArray(pointPosition(selected));
    emphasis=0;invalidate();
  }
  function drawNodes(factor){
    if(!nodes)return false;
    let moving=false;
    baseColor.lerpColors(day.base,night.base,theme);selectedColor.lerpColors(day.accent,night.accent,theme);
    points.forEach((point,i)=>{
      const target=point.id===selectedId?1:highlights.has(point.id)?.8:related.has(point.id)?.45:0;
      weights[i]+=(target-weights[i])*factor;moving ||= Math.abs(target-weights[i])>.001;
      dummy.position.fromArray(pointPosition(point));dummy.scale.setScalar(.035+.025*weights[i]);dummy.updateMatrix();nodes.setMatrixAt(i,dummy.matrix);
      // Unselected records keep their normal colour, including during a new
      // selection. Theme interpolation is independent of selection emphasis.
      const tone=tones[toneFor(point)];color.lerpColors(tone[0],tone[1],theme).lerp(selectedColor,weights[i]);nodes.setColorAt(i,color);
    });
    nodes.instanceMatrix.needsUpdate=true;nodes.instanceColor.needsUpdate=true;return moving;
  }
  function applyTheme(){
    baseColor.lerpColors(day.base,night.base,theme);selectedColor.lerpColors(day.accent,night.accent,theme);
    neighbourhoodMaterial.color.copy(baseColor);neighbourhoodMaterial.opacity=THREE.MathUtils.lerp(.32,.38,theme);
    linesMaterial.color.copy(selectedColor);ring.material.color.copy(selectedColor);
    haloMaterial.color.copy(baseColor);haloMaterial.opacity=THREE.MathUtils.lerp(.12,.4,theme);
    light.intensity=THREE.MathUtils.lerp(3,8,theme);
  }
  return {
    group,miniature,
    get zoom(){return currentZoom;},
    setPoints(value){
      if(points===value&&nodes)return;
      points=value;weights=points.map(()=>0);
      // Fit the full orbit and allowed tilt above the table. The wider cloud
      // can sit lower without any of its points crossing the tabletop.
      const coordinates=points.map(archivePointPosition);
      const radius=Math.max(.001,...coordinates.map(position=>Math.hypot(...position)));
      const vertical=Math.max(.001,...coordinates.map(([x,y,z])=>{
        const horizontal=Math.hypot(x,z),tilt=Math.min(MAX_PITCH,Math.atan2(horizontal,Math.abs(y)));
        return Math.abs(y)*Math.cos(tilt)+horizontal*Math.sin(tilt);
      }));
      const fit=Math.min(1,1.9/radius,1.3/vertical);
      positions=new Map(points.map(point=>[point.id,archivePointPosition(point).map(value=>value*fit)]));
      if(nodes){content.remove(nodes);nodes.geometry.dispose();}
      nodes=new THREE.InstancedMesh(new THREE.SphereGeometry(1,10,8),nodesMaterial,points.length);nodes.frustumCulled=false;content.add(nodes);
      const edges=new Set(),vertices=[];
      for(const point of points){
        // Two strongest semantic neighbours keep the overview legible.
        for(const nearest of nearbyArchivePoints(points,point.id,2)){
          const key=[point.id,nearest.id].sort((a,b)=>a-b).join('/');
          if(edges.has(key))continue;
          edges.add(key);vertices.push(...pointPosition(point),...pointPosition(nearest));
        }
      }
      neighbourhood.geometry.dispose();neighbourhood.geometry=new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));
      halos.geometry.dispose();halos.geometry=new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(points.flatMap(pointPosition),3));
      rebuildSelection();applyTheme();drawNodes(1);
    },
    select(id,matching=[]){
      const changed=id!==selectedId;
      selectedId=id;highlights=new Set(matching);rebuildSelection();
      if(selected&&matching.length&&changed){zoom=Math.max(zoom,1.12);rotation+=.16;}
      if(id==null&&!matching.length)zoom=1;
    },
    setHovered(value,source='pointer'){const had=hoverSources.has(source);if(value)hoverSources.add(source);else hoverSources.delete(source);if(had!==value)invalidate();},
    rotate(dx,dy){rotation+=dx*.006;pitch=THREE.MathUtils.clamp(pitch+dy*.004,-MAX_PITCH,MAX_PITCH);invalidate();},
    zoomBy(factor){zoom=archiveZoom(zoom*factor);invalidate();},
    resetZoom(){zoom=currentZoom=1;},
    reset(){rotation=-.38;pitch=0;zoom=1;invalidate();},
    update(dt,camera,reducedMotion){
      const orbit=points.length>0&&!hoverSources.size&&!reducedMotion;
      if(orbit)rotation+=dt*.065;
      const factor=reducedMotion?1:1-Math.exp(-dt*8);
      currentRotation+=(rotation-currentRotation)*factor;currentPitch+=(pitch-currentPitch)*factor;currentZoom+=(zoom-currentZoom)*factor;
      const hoverScale=hoverSources.has('pointer')||hoverSources.has('gesture')?1.035:1;
      currentHoverScale+=(hoverScale-currentHoverScale)*(reducedMotion?1:1-Math.exp(-dt*14));content.scale.setScalar(currentHoverScale);
      emphasis+=(1-emphasis)*factor;
      volume.rotation.set(currentPitch,currentRotation,0);volume.updateWorldMatrix(true,true);
      if(ring.visible){const world=camera.getWorldQuaternion(new THREE.Quaternion()),parent=content.getWorldQuaternion(new THREE.Quaternion()).invert();ring.quaternion.copy(parent.multiply(world));}
      ring.material.opacity=.85*emphasis;linesMaterial.opacity=.75*emphasis;
      const linePositions=lines.geometry.getAttribute('position');
      if(linePositions&&lineEnds.length){for(let i=0;i<lineEnds.length;i+=6)for(let axis=0;axis<3;axis++)linePositions.array[i+3+axis]=THREE.MathUtils.lerp(lineEnds[i+axis],lineEnds[i+3+axis],emphasis);linePositions.needsUpdate=true;}
      const nodesMoving=drawNodes(factor);
      return orbit||nodesMoving||1-emphasis>.001||Math.abs(hoverScale-currentHoverScale)>.0001||Math.abs(rotation-currentRotation)+Math.abs(pitch-currentPitch)+Math.abs(zoom-currentZoom)>.0001;
    },
    contains(clientX,clientY,rect,camera){
      if(!nodes||!rect.width||!rect.height)return false;
      controlVolume.updateWorldMatrix(true,false);camera.updateMatrixWorld();
      pointer.set((clientX-rect.left)/rect.width*2-1,1-(clientY-rect.top)/rect.height*2);raycaster.setFromCamera(pointer,camera);
      return raycaster.intersectObject(controlVolume).length>0;
    },
    pick(clientX,clientY,rect,camera){
      if(!nodes)return null;
      content.updateWorldMatrix(true,false);camera.updateMatrixWorld();
      let closest=null,distance=16;
      for(const point of points){
        const p=new THREE.Vector3().fromArray(pointPosition(point)).applyMatrix4(content.matrixWorld).project(camera);if(p.z< -1||p.z>1)continue;
        const d=Math.hypot(rect.left+(p.x+1)*rect.width/2-clientX,rect.top+(1-p.y)*rect.height/2-clientY);
        if(d<distance){distance=d;closest=point;}
      }
      return closest;
    },
    setTheme(dark){themeFrom=theme;themeTo=Number(dark);},
    setThemeProgress(progress){theme=THREE.MathUtils.lerp(themeFrom,themeTo,progress);applyTheme();drawNodes(0);},
    dispose(){haloTexture.dispose();},
  };
}
